namespace CleanArchitecture.Blazor.Application.Features.Vehicles.Specifications;
#nullable disable warnings
/// <summary>
/// Specification class for advanced filtering of Vehicles.
/// </summary>
public class VehicleAdvancedSpecification : Specification<Vehicle>
{
    public VehicleAdvancedSpecification(VehicleAdvancedFilter filter)
    {
        DateTime today = DateTime.UtcNow;
        var todayrange = today.GetDateRange(VehicleListView.TODAY.ToString(), filter.CurrentUser.LocalTimeOffset);
        var last30daysrange = today.GetDateRange(VehicleListView.LAST_30_DAYS.ToString(),filter.CurrentUser.LocalTimeOffset);

        Query.Where(q => q.Name != null)
             .Where(x=>x.ZoneId==filter.ZoneId,filter.ZoneId!=null)
             .Where(x=>x.Zone.CarparkId==filter.CarparkId,filter.CarparkId!=null)
             .Where(filter.Keyword,!string.IsNullOrEmpty(filter.Keyword))
             .Where(q => q.CreatedById == filter.CurrentUser.UserId, filter.ListView == VehicleListView.My && filter.CurrentUser is not null)
             .Where(x => x.CreatedAt >= todayrange.Start && x.CreatedAt < todayrange.End.AddDays(1), filter.ListView == VehicleListView.TODAY)
             .Where(x => x.CreatedAt >= last30daysrange.Start, filter.ListView == VehicleListView.LAST_30_DAYS);
       
    }
}
